for _hint in ("Secure mode · Instructor PIN to exit", "Q: finish when not typing", "Q: finish exam"):
    _STUDENT[f"FPS: {{fps}} · Local CPU · {_hint}"] = {
        "ru": f"FPS: {{fps}} · Локальный CPU · {_STUDENT[_hint]['ru']}",
        "kk": f"FPS: {{fps}} · Жергілікті CPU · {_STUDENT[_hint]['kk']}",
    }
    _STUDENT[f"FPS: warming up · Local CPU · {_hint}"] = {
        "ru": f"FPS: подготовка · Локальный CPU · {_STUDENT[_hint]['ru']}",
        "kk": f"FPS: дайындалуда · Жергілікті CPU · {_STUDENT[_hint]['kk']}",
    }

# A timeline presents spaced event names while records retain underscore enums.
_STUDENT.update({source.replace("_", " "): translated
                 for source, translated in _COMMON.items()
                 if "_" in source and source.isupper()})

# Shared keys have one authoritative translation even when used by both roles.
TRANSLATIONS = {source: translated for source, translated in _STUDENT.items()
                if source not in _COMMON and source not in _REPORT}
